mapper.update:
UPDATE refund_notification_task
SET status = 'DONE',
    lease_until = NULL,
    last_error = NULL,
    updated_at = #{updatedAt}
WHERE event_id = #{eventId}
  AND status = 'PROCESSING'
  AND attempts = #{attempts}

UPDATE refund_notification_task
SET status = 'PENDING',
    lease_until = NULL,
    last_error = #{lastError,jdbcType=VARCHAR},
    next_retry_at = #{nextRetryAt},
    updated_at = #{updatedAt}
WHERE event_id = #{eventId}
  AND status = 'PROCESSING'
  AND attempts = #{attempts}
